---修改按钮点击回调
function FightTeamPresetModifyNamePopup:ModifyBtnOnClickHandler()
    if string.isEmpty(self:GetInputName()) then
        GameUtils.Toast(localize('编队名称不能为空'))
        return
    end
    GameUtils.Request(Interfaces.OverseaTeamCheckName, {name = self:GetInputName()}, function(request, response)
        if checkInt(response.data.isValid) == 0 then
            GameUtils.Toast(response.data.errMsg)
            return
        else
            Events.Broadcast(Constants.EventNames.MODIFY_TEAM_NAME, self:GetInputName())
            UIModule.CloseDialog(self.controller)
        end
    end)
end
--endregion handler

